-- ============================================================
-- DATOS TECNICOS GARANTIZADOS — carga completa (v1.103)
--
-- Origen: planilla "DATOS TECNICOS GARANTIZADOS.xlsx" (87 modelos).
-- REEMPLAZA a supabase_datos_tecnicos_v1.55.sql, que importaba solo 15 de las
-- 29 columnas utiles de la planilla y ademas REDONDEABA los valores.
--
-- QUE SUMA ESTA VERSION
--
-- 1. TOLERANCIAS POR MODELO (tol_*, us_un, is_io). Hasta ahora vivian
--    hardcodeadas en `lib/ensayoPerdidas.ts` (ESCALA_PERDIDAS, ESCALA_IO,
--    ESCALA_UCC, ESCALA_TOTALES). Coincidian con la planilla, pero el dia que un
--    modelo tenga otra tolerancia nadie se iba a enterar.
--
-- 2. POTENCIA DE INSTRUMENTOS POR MODELO (pins_po, pins_pcc). Hoy la app las
--    guarda en el localStorage de cada navegador como constante del banco,
--    igual para todos los modelos. En la planilla varian por modelo
--    (0, 1, 2, 3, 7, 8, 11, 15 VA). Son datos distintos con el mismo nombre.
--
-- 3. PRECISION COMPLETA. El v1.55 guardaba i2n = 90.9 donde el valor real es
--    90.93266739736606. No cambiaba ningun resultado, pero no habia motivo para
--    perder precision al importar.
--
-- REGLA DE NEGOCIO (sin cambios desde v1.55): los parametros se definen por
-- CODIGO CORTO ("TTD 160/13") y valen para TODAS las variantes constructivas de
-- ese codigo — cobre o aluminio, llenado integral o tanque de expansion,
-- monoposte o plataforma. Por eso son 87 filas y no 255: la app extrae el codigo
-- del nombre largo de SAP.
--
-- SOBRE tol_io_pct = 0: la planilla trae 0 en los 87 modelos, pero el documento
-- "CALCULO PARA ENSAYO DE PERDIDAS" dice que la corriente de vacio tiene
-- tolerancia de +30%. Se importa el 0 tal cual viene, y es el FRONT el que lo
-- trata como "sin dato" y cae al +30%. Decision de Lorenzo (8/9/2026): manda el
-- documento de calculo. Si Laboratorio carga un numero real en esa columna, ese
-- numero pasa a mandar sin tocar codigo.
--
-- Las columnas van en snake_case a proposito: "Ucc(%)" obligaria a comillas
-- dobles en cada consulta. El front resuelve los nombres por alias.
--
-- Idempotente: se puede volver a correr (borra y recarga).
-- ============================================================

drop table if exists datos_tecnicos;

create table datos_tecnicos (
  modelo          text primary key,   -- codigo corto: "TTD 160/13"
  tipo            text not null,      -- TTD | TTR | TMR | TBR | TTS
  iram            integer,            -- norma IRAM aplicable (2250 | 2269 | 2476)

  -- ---------- valores nominales garantizados ----------
  sn              numeric,            -- potencia nominal (kVA)
  un1             numeric,            -- tension primaria (kV)
  un2             numeric,            -- tension secundaria (kV)
  i1n             numeric,            -- corriente primaria (A)
  i2n             numeric,            -- corriente secundaria (A)
  ucc_pct         numeric,            -- tension de cortocircuito (%)
  u1cc_1f         numeric,            -- tension de cc monofasica (V)
  io_pct          numeric,            -- corriente de vacio (%)
  i2o             numeric,            -- corriente de vacio secundaria (A)
  po              numeric,            -- perdidas en vacio (W)
  pcc             numeric,            -- perdidas en cortocircuito (W)

  -- ---------- tolerancias de norma, en % sobre el nominal ----------
  tol_ucc_pct     numeric,            -- ucc%: +/- (bilateral)
  tol_io_pct      numeric,            -- io%: ver nota de la cabecera
  tol_po_pct      numeric,            -- Po: + (unilateral)
  tol_pcc_pct     numeric,            -- Pcc: + (unilateral)
  tol_pt_pct      numeric,            -- perdidas totales: + (unilateral)

  -- ---------- criterio del ensayo de sobreexcitacion ----------
  -- El ensayo de vacio se repite a una tension mayor a la nominal (us_un veces)
  -- y la corriente no debe superar is_io veces la corriente de vacio. Es el
  -- control de saturacion del nucleo que el protocolo ya calcula pero que hasta
  -- ahora no tenia contra que compararse.
  us_un           numeric,            -- 1.05 o 1.10 segun familia
  is_io           numeric,            -- 2.2 o 3 segun familia

  -- ---------- consumo de los instrumentos de medicion ----------
  pins_po         numeric,            -- potencia de instrumentos en vacio (VA)
  pins_pcc        numeric,            -- potencia de instrumentos en cortocircuito (VA)
  zins            numeric,            -- impedancia de los instrumentos (ohm)
  ins_io          numeric,            -- corriente usada en el calculo; = i2o cuando i2o existe
  ti              numeric,            -- relacion del transformador de intensidad
  io_pct_prima    numeric,            -- io% recalculado; solo en los modelos grandes sin i2o

  -- ---------- derivados de la planilla ----------
  relacion_po_pcc numeric,            -- Po/Pcc
  c               numeric             -- coeficiente de la planilla
);

comment on table datos_tecnicos is
  'Parametros normativos garantizados por codigo de modelo (v1.103). Aplican a '
  'todas las variantes constructivas. Maestro de SOLO LECTURA: la app nunca lo escribe.';

insert into datos_tecnicos
  (modelo, tipo, iram, sn, un1, un2, i1n, i2n, ucc_pct, u1cc_1f, io_pct, i2o, po, pcc,
   tol_ucc_pct, tol_io_pct, tol_po_pct, tol_pcc_pct, tol_pt_pct, us_un, is_io,
   pins_po, pins_pcc, zins, ins_io, ti, io_pct_prima, relacion_po_pcc, c)
