-- Busquedas por familia (el front filtra en memoria, pero no molesta).
create index if not exists idx_datos_tecnicos_tipo on datos_tecnicos (tipo);

-- ============================================================
-- RLS: toda la planta puede LEER; nadie escribe desde la app (es un maestro).
-- Sin esta politica el fetch devuelve vacio y el panel no muestra nada — que es
-- exactamente el sintoma de "todos los garantizados en guion".
-- ============================================================
alter table datos_tecnicos enable row level security;

drop policy if exists datos_tecnicos_leer on datos_tecnicos;
create policy datos_tecnicos_leer on datos_tecnicos
  for select to authenticated
  using (true);

-- ============================================================
-- VERIFICACION
-- ============================================================
-- Debe dar 87:
--   select count(*) from datos_tecnicos;
-- Debe dar TTD=32, TTS=21, TTR=16, TBR=10, TMR=8:
--   select tipo, count(*) from datos_tecnicos group by tipo order by tipo;
-- El modelo del protocolo que salia en blanco:
--   select modelo, sn, un1, un2, po, pcc, ucc_pct, io_pct, pins_po, pins_pcc
--   from datos_tecnicos where modelo = 'TTD 63/33';
-- Los 10 modelos grandes sin Po/Pcc garantizados (es correcto que esten nulos):
--   select modelo from datos_tecnicos where po is null order by modelo;
